INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(80204957, 'Karakuri Cash Cache', '机偶借金藏', '借カラクリ蔵', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1只名字带有「机巧」的怪兽发动。从自己卡组把1只4星以下的名字带有「机巧」的怪兽加入手卡，选择的怪兽的表示形式变更。'),
(3693034, 'Karakuri Cash Inn', '机偶借宿旅笼藏', '借カラクリ旅籠蔵', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1只「机巧」怪兽和对方场上1只效果怪兽为对象才能发动。那只自己怪兽的表示形式变更，那只对方怪兽的效果直到回合结束时无效。 ②：自己场上有「机巧」怪兽存在的场合，把墓地的这张卡除外，以场上1只表侧表示怪兽为对象才能发动。那只怪兽的表示形式变更。'),
(2924048, 'Karakuri Cash Shed', '机偶借金整备藏', '借カラクリ整備蔵', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '自己场上有名字带有「机巧」的怪兽表侧守备表示存在的场合才能发动。对方发动的魔法·陷阱卡的发动无效并破坏。'),
(75690317, 'Karakuri Gama mdl 4624 "Shirokunishi"', '机偶蛤蟆 四六贰四', 'カラクリ蝦蟇 四六弐四', 'Tuner Monster', 'Machine', 'EARTH', 1, 200, 1000, '这个卡名的③的效果1回合只能使用1次。 ①：这张卡可以攻击的场合必须作出攻击。 ②：这张卡被选择作为攻击对象的场合发动。这张卡的表示形式变更。 ③：把墓地的这张卡除外，以自己场上1只「机巧」怪兽为对象才能发动。那只怪兽的表示形式变更。这个效果在对方回合也能发动。'),
(11699941, 'Karakuri Gama Oil', '机偶蛤蟆油', 'カラクリ蝦蟇油', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己墓地1只「机巧」怪兽为对象才能把这张卡发动。那只怪兽特殊召唤，把这张卡装备。 ②：1回合1次，自己场上的表侧表示的「机巧」怪兽的表示形式变更的场合发动。装备怪兽的攻击力·守备力上升500。'),
(16708652, 'Karakuri Gold Dust', '机巧粉', 'カラクリ粉', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '选择场上表侧攻击表示存在的2只名字带有「机巧」的怪兽发动。选择的1只怪兽变成守备表示，另1只怪兽的攻击力直到结束阶段时上升变成守备表示的怪兽的攻击力数值。这个效果在战斗阶段时才能发动。'),
(79178930, 'Karakuri Klock', '时限机巧爆弹', '時限カラクリ爆弾', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '表侧守备表示存在的名字带有「机巧」的怪兽被选择作为攻击对象时才能发动。对方场上表侧表示存在的怪兽全部破坏。'),
(24621460, 'Karakuri Komachi mdl 224 "Ninishi"', '机偶小町 贰贰四', 'カラクリ小町 弐弐四', 'Tuner Monster', 'Machine', 'EARTH', 3, NULL, 1900, '这张卡可以攻击的场合必须作出攻击。场上表侧表示存在的这张卡被选择作为攻击对象时，这张卡的表示形式变更。只要这张卡在场上表侧表示存在，自己的主要阶段时只有1次，自己在通常召唤外加上可以把1只名字带有「机巧」的怪兽召唤。'),
(30230789, 'Karakuri Merchant mdl 177 "Inashichi"', '机偶商人 壹七七', 'カラクリ商人 壱七七', 'Effect Monster', 'Machine', 'EARTH', 2, 500, 1500, '这张卡可以攻击的场合必须作出攻击。场上表侧攻击表示存在的这张卡被选择作为攻击对象时，这张卡的表示形式变成守备表示。这张卡召唤成功时，从自己卡组把1张名字带有「机巧」的卡加入手卡。'),
(24150026, 'Karakuri Muso mdl 818 "Haipa"', '机偶无双 八壹八', 'カラクリ無双 八壱八', 'Effect Monster', 'Machine', 'EARTH', 4, 2100, 1100, '这张卡可以攻击的场合必须作出攻击。场上表侧攻击表示存在的这张卡被选择作为攻击对象时，这张卡的表示形式变成守备表示。这张卡攻击的场合，战斗阶段结束时变成守备表示。'),
(93724592, 'Karakuri Ninja mdl 339 "Sazank"', '机巧忍者 三三九', 'カラクリ忍者 参参九', 'Effect Monster', 'Machine', 'EARTH', 3, 1200, 1200, '这张卡可以攻击的场合必须作出攻击。场上表侧攻击表示存在的这张卡被选择作为攻击对象时，这张卡的表示形式变成守备表示。这张卡反转时，选择场上表侧表示存在的1只怪兽送去墓地。此外，这张卡反转的回合，这张卡可以直接攻击对方玩家。'),
(50615578, 'Karakuri Ninja mdl 7749 "Nanashick"', '机偶忍者 七七四九', 'カラクリ忍者 七七四九', 'Effect Monster', 'Machine', 'EARTH', 5, 2200, 1800, '这张卡可以攻击的场合必须作出攻击。场上表侧表示存在的这张卡被选择作为攻击对象时，这张卡的表示形式变更。这张卡召唤成功时，可以从自己卡组抽出自己场上表侧守备表示存在的名字带有「机巧」的怪兽数量的卡。'),
(6276588, 'Karakuri Ninja mdl 919 "Kuick"', '机巧忍者 九一九', 'カラクリ忍者 九壱九', 'Effect Monster', 'Machine', 'EARTH', 4, 1700, 1500, '这张卡可以攻击的场合必须作出攻击。场上表侧表示存在的这张卡被选择作为攻击对象时，这张卡的表示形式变更。这张卡战斗破坏对方怪兽送去墓地时，选择自己墓地存在的1只4星以下的名字带有「机巧」的怪兽表侧守备表示特殊召唤。'),
(23874409, 'Karakuri Shogun mdl 00 "Burei"', '机偶将军 无零', 'カラクリ将軍 無零', 'Synchro Monster', 'Machine', 'EARTH', 7, 2600, 1900, '调整＋调整以外的机械族怪兽1只以上 这张卡同调召唤成功时，可以从自己卡组把1只名字带有「机巧」的怪兽特殊召唤。1回合1次，可以选择场上存在的1只怪兽，把表示形式变更。'),
(22751868, 'Karakuri Showdown Castle', '风云机偶城', '風雲カラクリ城', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的名字带有「机巧」的怪兽把对方场上表侧表示存在的怪兽选择作为攻击对象时，可以把那1只对方怪兽的表示形式变更。此外，场上表侧表示存在的这张卡被破坏送去墓地时，可以选择自己墓地存在的1只4星以上的名字带有「机巧」的怪兽特殊召唤。'),
(3846170, 'Karakuri Soldier mdl 236 "Nisamu"', '机偶兵 贰叁六', 'カラクリ兵 弐参六', 'Effect Monster', 'Machine', 'EARTH', 4, 1400, 200, '这张卡可以攻击的场合必须作出攻击。场上表侧攻击表示存在的这张卡被选择作为攻击对象时，这张卡的表示形式变成守备表示。这张卡被战斗破坏送去墓地时，可以从自己卡组把1只4星以下的名字带有「机巧」的怪兽表侧攻击表示特殊召唤。'),
(45688586, 'Karakuri Spider', '机巧蜘蛛', 'カラクリ蜘蛛', 'Effect Monster', 'Machine', 'EARTH', 2, 400, 500, '这张卡攻击的怪兽是暗属性的场合，那只怪兽破坏，伤害的计算适用。'),
(66976526, 'Karakuri Steel Shogun mdl 00X "Bureido"', '机偶大将军 无零怒', 'カラクリ大将軍 無零怒', 'Synchro Monster', 'Machine', 'EARTH', 8, 2800, 1700, '调整＋调整以外的机械族怪兽1只以上 ①：这张卡同调召唤成功时才能发动。从卡组把1只「机巧」怪兽特殊召唤。 ②：1回合1次，自己场上的表侧表示的「机巧」怪兽的表示形式变更的场合发动。自己从卡组抽1张。'),
(66625883, 'Karakuri Strategist mdl 248 "Nishipachi"', '机偶参谋 贰四八', 'カラクリ参謀 弐四八', 'Tuner Monster', 'Machine', 'EARTH', 3, 500, 1600, '这张卡可以攻击的场合必须作出攻击。场上表侧攻击表示存在的这张卡被选择作为攻击对象时，这张卡的表示形式变成守备表示。这张卡召唤·特殊召唤成功时，把场上存在的1只怪兽的表示形式变更。'),
(25904894, 'Karakuri Super Shogun mdl 00N "Bureibu"', '机偶大权现 无零武', 'カラクリ大権現 無零武', 'Synchro Monster', 'Machine', 'EARTH', 9, 3000, 1500, '调整＋调整以外的机械族怪兽1只以上 ①：这张卡同调召唤成功的场合才能发动。从卡组把1只「机巧」怪兽特殊召唤。 ②：只要这张卡在怪兽区域存在，自己的守备表示怪兽不会被战斗破坏。 ③：1回合1次，自己场上的表侧表示的「机巧」怪兽的表示形式变更的场合，以对方场上1张卡为对象才能发动。那张卡除外。'),
(33184236, 'Karakuri Trick House', '机巧屋敷', 'カラクリ屋敷', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的名字带有「机巧」的怪兽的表示形式变更时才能发动。选择场上存在的1张卡破坏。'),
(70271583, 'Karakuri Watchdog mdl 313 "Saizan"', '机偶守卫 叁壹叁', 'カラクリ守衛 参壱参', 'Tuner Monster', 'Machine', 'EARTH', 4, 600, 1800, '这张卡可以攻击的场合必须作出攻击。场上表侧表示存在的这张卡被选择作为攻击对象时，这张卡的表示形式变更。这张卡的战斗让自己受到战斗伤害时，自己场上表侧表示存在的名字带有「机巧」的全部怪兽的攻击力·守备力直到结束阶段时上升800。此外，这张卡只要在场上表侧攻击表示存在不会被战斗破坏。'),
(23289281, 'Karate Man', '空手道家', 'カラテマン', 'Effect Monster', 'Warrior', 'EARTH', 3, 1000, 1000, '1回合1次，自己的主要阶段时才能发动。这张卡的攻击力直到结束阶段时变成原本攻击力2倍的数值。这个效果使用的场合，这张卡在结束阶段时破坏。'),
(54541900, 'Karbonala Warrior', '炭烧战士', 'カルボナーラ戦士', 'Fusion Monster', 'Warrior', 'EARTH', 4, 1500, 1200, '「磁力战士1号」＋「磁力战士2号」'),
(71587526, 'Karma Cut', '因果切断', '因果切断', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：丢弃1张手卡，以对方场上1只表侧表示怪兽为对象才能发动。那只对方的表侧表示怪兽除外。这个效果除外的卡的同名卡在对方墓地存在的场合，再把那些同名卡全部除外。'),
(78348934, 'Karma of the Destruction Swordsman', '破坏剑士的宿命', '破壊剣士の宿命', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '「破坏剑士的宿命」的①②的效果1回合各能使用1次。 ①：以对方墓地最多3只相同种族的怪兽为对象才能发动。那些怪兽除外，选自己场上1只「破坏之剑士」怪兽或者「破坏剑」怪兽，直到回合结束时那个攻击力·守备力上升除外的怪兽数量×500。 ②：这张卡在墓地存在的场合，从手卡丢弃1张「破坏剑」卡才能发动。墓地的这张卡加入手卡。'),
(52512994, 'Kasha', '火车', '火車', 'Effect Monster', 'Zombie', 'EARTH', 8, -1, 1000, '这张卡不能通常召唤。自己场上的不死族怪兽是2只以上的场合才能特殊召唤。 ①：这张卡特殊召唤成功的场合发动。这张卡以外的场上的怪兽全部回到持有者卡组。原本种族是不死族的表侧表示怪兽回到卡组的场合，这张卡的攻击力变成那些怪兽数量×1000。'),
(82286798, 'Kashtira Akstra', '怒刹帝利・阿刹特罗', 'クシャトリラ・アクストラ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上的表侧表示的「俱舍怒威族」超量怪兽被战斗·效果破坏的场合才能发动。从自己的手卡·卡组·场上选1只「维萨斯-斯塔弗罗斯特」除外，从额外卡组把1只「维舍斯-阿修特罗德」无视召唤条件特殊召唤。 ②：这张卡被除外的场合，以除外的1只自己的「维萨斯-斯塔弗罗斯特」为对象才能发动。那只怪兽加入手卡。'),
(48626373, 'Kashtira Arise-Heart', '怒刹帝利・亚拉眦哈忒', 'クシャトリラ・アライズハート', 'XYZ Monster', 'Machine', 'DARK', 7, 3000, 3000, '7星怪兽×3 「俱舍怒威族·阿莱斯哈特」在「俱舍怒威族的香格里拉茧」把效果发动的回合有1次也能在自己的「俱舍怒威族」怪兽上面重叠来超量召唤。 ①：被送去墓地的卡不去墓地而除外。 ②：每次卡被除外发动（同一连锁上最多1次）。选除外中的1张卡作为这张卡的超量素材。 ③：双方回合1次，把这张卡3个超量素材取除，以场上1张卡为对象才能发动。那张卡里侧表示除外。'),
(33925864, 'Kashtira Big Bang', '怒刹帝利・六世坏根清净', '六世壊根清浄', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：场上有「俱舍怒威族」超量怪兽存在的场合才能发动。双方直到自身场上的怪兽变成1只为止必须里侧表示除外。 ②：这张卡被除外的场合，以自己场上1只「俱舍怒威族」超量怪兽为对象才能发动。那只怪兽作为超量素材中的1只自己的「俱舍怒威族」怪兽加入手卡。那之后，可以把那只怪兽从手卡特殊召唤。'),
(69540484, 'Kashtira Birth', '怒刹帝利・诞生', 'クシャトリラ・バース', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②③的效果1回合各能使用1次。 ①：自己在7星怪兽召唤的场合需要的解放可以不用。 ②：自己主要阶段才能发动。从自己墓地的怪兽以及除外的自己怪兽之中选超量怪兽以外的1只「俱舍怒威族」怪兽特殊召唤。 ③：对方把魔法卡的效果发动的场合，若自己场上有「俱舍怒威族」怪兽存在，以对方墓地3张卡为对象才能发动。那些卡里侧表示除外。'),
(32909498, 'Kashtira Fenrir', '怒刹帝利・芬里尔', 'クシャトリラ・フェンリル', 'Effect Monster', 'Psychic', 'EARTH', 7, 2400, 2400, '这个卡名的②③的效果1回合各能使用1次。 ①：自己场上没有怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：自己主要阶段才能发动。从卡组把1只「俱舍怒威族」怪兽加入手卡。 ③：这张卡的攻击宣言时或者对方把怪兽的效果发动的场合，以对方场上1张表侧表示的卡为对象才能发动。那张卡里侧表示除外。'),
(94392192, 'Kashtira Ogre', '怒刹帝利・食人魔', 'クシャトリラ・オーガ', 'Effect Monster', 'Psychic', 'WATER', 7, 2800, 1000, '这个卡名的②③的效果1回合各能使用1次。 ①：自己场上没有怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：自己主要阶段才能发动。从卡组把1张「俱舍怒威族」陷阱卡加入手卡。 ③：这张卡的攻击宣言时或者对方把怪兽的效果发动的场合才能发动。从对方卡组上面把最多5张卡翻开，从那之中选1张里侧表示除外。剩下的卡用原本的顺序回到卡组上面。'),
(8953369, 'Kashtira Overlap', '怒刹帝利・交迭', 'クシャトリラ・オーバーラップ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以场上1只怪兽为对象才能发动。从自己的手卡·墓地以及自己·对方场上的表侧表示怪兽之中选1只攻击力1500/守备力2100的怪兽除外，作为对象的怪兽的攻击力上升1500。 ②：这张卡被除外的场合，若自己场上有「俱舍怒威族」怪兽存在，以对方场上1只效果怪兽为对象才能发动。那只怪兽的效果直到回合结束时无效。'),
(21639276, 'Kashtira Preparations', '怒刹帝利・准备', 'クシャトリラ・プリペア', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方回合可以发动。从手卡的怪兽以及除外的自己怪兽之中选1只「俱舍怒威族」怪兽特殊召唤。 ②：这张卡已在魔法与陷阱区域存在的状态，对方把陷阱卡的效果发动的场合，若自己场上有「俱舍怒威族」怪兽存在则能发动。把对方手卡确认，选那之内的1张里侧表示除外。'),
(31149212, 'Kashtira Riseheart', '怒刹帝利・拉眦哈忒', 'クシャトリラ・ライズハート', 'Effect Monster', 'Warrior', 'FIRE', 4, 1500, 2100, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有「俱舍怒威族」怪兽存在的场合才能发动。这张卡从手卡特殊召唤。这个回合，自己不是超量怪兽不能从额外卡组特殊召唤。 ②：这张卡召唤·特殊召唤成功的回合的自己主要阶段，从卡组把「俱舍怒威族·莱斯哈特」以外的1张「俱舍怒威族」卡除外才能发动。从对方卡组上面把3张卡里侧表示除外，这张卡的等级变成7星。'),
(73542331, 'Kashtira Shangri-Ira', '怒刹帝利・香格里拉', 'クシャトリラ・シャングリラ', 'XYZ Monster', 'Psychic', 'FIRE', 7, NULL, 3000, '7星怪兽×2只以上 这个卡名的①的效果1回合只能使用1次。 ①：自己·对方的准备阶段才能发动。从卡组把1只「俱舍怒威族」怪兽特殊召唤。 ②：每次对方的卡被里侧表示除外，指定没有使用的主要怪兽区域或者魔法与陷阱区域1处才能发动。指定的区域在这只怪兽表侧表示存在期间不能使用。 ③：场上的这张卡被战斗·效果破坏的场合，可以作为代替把这张卡1个超量素材取除。'),
(68304193, 'Kashtira Unicorn', '怒刹帝利・独角兽', 'クシャトリラ・ユニコーン', 'Effect Monster', 'Psychic', 'WIND', 7, 2500, 2100, '这个卡名的②③的效果1回合各能使用1次。 ①：自己场上没有怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：自己主要阶段才能发动。从卡组把1张「俱舍怒威族」魔法卡加入手卡。 ③：这张卡的攻击宣言时或者对方把怪兽的效果发动的场合才能发动。把对方的额外卡组确认，选那之内的1只怪兽里侧表示除外。'),
(34447918, 'Kashtiratheosis', '怒刹帝利・六世坏他化自在天', '六世壊他化自在天', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1只「俱舍怒威族」怪兽为对象才能发动。和那只怪兽属性不同的1只「俱舍怒威族」怪兽从卡组守备表示特殊召唤。这张卡的发动后，直到回合结束时自己不是超量怪兽不能从额外卡组特殊召唤。 ②：这张卡被除外的场合，以「六世坏他化自在天」以外的除外的1张自己的「俱舍怒威族」卡为对象才能发动。那张卡加入手卡。'),
(81179446, 'Kattapillar', '青虫', '青虫', 'Normal Monster', 'Insect', 'EARTH', 1, 250, 300, '吐丝攻击。不知道以后会长成什么样子的虫。'),
(51554871, 'Kayenn, the Master Magma Blacksmith', '灼热工的巨匠 火炎', '灼熱工の巨匠カエン', 'Effect Monster', 'Rock', 'FIRE', 3, 1200, 200, '把自己墓地存在的这张卡从游戏中除外发动。自己场上表侧表示存在的名字带有「熔岩」的怪兽的攻击力上升400。'),
(62340868, 'Kazejin', '风魔神－休迦', '風魔神－ヒューガ', 'Effect Monster', 'Spellcaster', 'WIND', 7, 2400, 2200, '①：只在这张卡在场上表侧表示存在才有1次，这张卡被攻击的伤害计算时，以1只攻击怪兽为对象才能发动。那只攻击怪兽的攻击力变成0。'),
(99529628, 'Keaf, Murk of the Ghoti', '游魊之胧 基夫', 'ゴーティスの朧キーフ', 'Effect Monster', 'Fish', 'WATER', 2, NULL, 1500, '这个卡名的①②③的效果1回合各能使用1次。 ①：场上有鱼族怪兽存在的场合才能发动。这张卡从手卡特殊召唤。 ②：对方场上有怪兽特殊召唤的场合，以那之内的1只怪兽和自己的除外状态的1只6星以下的鱼族怪兽为对象才能发动。作为对象的对方怪兽和这张卡除外，作为对象的自己怪兽特殊召唤。 ③：这张卡被除外的下个回合的准备阶段才能发动。除外状态的这张卡特殊召唤。'),
(66736884, 'Keel, Shipwright Fur Hire', '空牙团的船匠 基尔', '空牙団の船匠 キール', 'Link Monster', 'Sea Serpent', 'WATER', NULL, 1800, NULL, '种族不同的怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡连接召唤的场合才能发动。从卡组把1张「空牙团」魔法·陷阱卡或「飞龙艇-幻舵拉」在自己场上盖放。这个回合，自己不是「空牙团」怪兽不能特殊召唤。 ②：对方回合才能发动。墓地的这张卡除外，从手卡把1只「空牙团」怪兽特殊召唤。那之后，场上的原本攻击力最高的怪兽在对方场上存在的场合，可以让另1只特殊召唤。'),
(48048590, 'Keeper of Dragon Magic', '龙魔导之保卫者', '竜魔導の守護者', 'Effect Monster', 'Dragon', 'DARK', 4, 1800, 1300, '这个卡名的①②的效果1回合各能使用1次，这张卡的效果发动的回合，自己不是融合怪兽不能从额外卡组特殊召唤。 ①：这张卡召唤·特殊召唤的场合，丢弃1张手卡才能发动。从卡组把1张「融合」通常魔法卡加入手卡。 ②：把额外卡组1只融合怪兽给对方观看才能发动。那只怪兽有卡名记述的1只融合素材怪兽从自己墓地里侧守备表示特殊召唤。'),
(66752837, 'Keeper of the Shrine', '灵庙的守卫者', '霊廟の守護者', 'Effect Monster', 'Dragon', 'DARK', 4, NULL, 2100, '这个卡名的②的效果1回合只能使用1次。 ①：龙族怪兽上级召唤的场合，这张卡可以作为2只的数量解放。 ②：这张卡在手卡·墓地存在，「灵庙守护者」以外的场上的表侧表示的龙族怪兽被效果送去墓地的场合或者被战斗破坏送去墓地的场合才能发动。这张卡特殊召唤。送去墓地的怪兽是通常怪兽的场合，可以再选自己墓地1只龙族通常怪兽加入手卡。'),
(54878498, 'Kelbek', '凯尔柏克', 'ケルベク', 'Effect Monster', 'Fairy', 'EARTH', 4, 1500, 1800, '向这张卡攻击的怪兽回到持有者手卡。伤害计算适用。'),
(25926710, 'Kelbek the Ancient Vanguard', '古尖兵 凯尔柏克', '古尖兵ケルベク', 'Effect Monster', 'Fairy', 'EARTH', 4, 1500, 1800, '这个卡名的①②的效果1回合各能使用1次。 ①：从手卡·卡组有卡被送去对方墓地的场合，以对方场上1只特殊召唤的怪兽为对象才能发动。这张卡从手卡特殊召唤。那之后，作为对象的怪兽回到持有者手卡。 ②：这张卡从手卡·卡组送去墓地的场合才能发动。从双方卡组上面把5张卡送去墓地。那之后，自己墓地有「现世与冥界的逆转」存在的场合，可以从自己墓地选1张陷阱卡在自己场上盖放。'),
(80441106, 'Keldo', '凯尔多', 'ケルドウ', 'Effect Monster', 'Fairy', 'EARTH', 4, 1200, 1600, '这张卡被战斗破坏送去墓地时，从对方墓地里选择2张卡回到对方卡组。'),
(63542003, 'Keldo the Sacred Protector', '宿神像 凯尔多', '宿神像ケルドウ', 'Effect Monster', 'Fairy', 'EARTH', 4, 1200, 1600, '这个卡名的①②的效果1回合各能使用1次。 ①：从手卡丢弃1只其他的天使族·地属性怪兽才能发动。这张卡从手卡特殊召唤。那之后，从卡组把1张「现世与冥界的逆转」或者有那个卡名记述的卡加入手卡。 ②：自己·对方回合，把场上·墓地的这张卡除外，以自己·对方的墓地的卡合计最多5张为对象才能发动。那些卡回到卡组。自己的场上以及墓地没有「现世与冥界的逆转」存在的场合，这个效果的对象变成最多3张。'),
(25131968, 'Ken the Warrior Dragon', '毘龙之谦', '毘龍之謙', 'Effect Monster', 'Warrior', 'LIGHT', 3, 1300, 1550, '这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。从手卡·卡组把1只「虎菱之玄」在对方场上守备表示特殊召唤。 ②：这张卡用「虎菱之玄」的效果特殊召唤的场合发动。对方抽2张。那之后，对方选1张手卡丢弃。 ③：自己·对方的战斗阶段结束时发动。场上的这张卡回到手卡。'),
(94503794, 'Kerzebs, the Gaoled Glutton', '漆梏之喰兽 凯尔泽布斯', '漆梏の喰獣 ケルゼブス', 'XYZ Monster', 'Beast', 'DARK', 7, 700, 2500, '7星怪兽×2只以上 这个卡名的③的效果1回合只能使用1次。 ①：这张卡的攻击力上升这张卡的超量素材数量×700。 ②：通常·速攻魔法卡发动时才能发动（同一连锁上最多1次）。场上的那张卡作为表侧表示的这张卡的超量素材，这张卡不受那个发动的效果影响。 ③：自己·对方的结束阶段才能发动。这张卡作为超量素材中的1张魔法卡在自己场上盖放。'),
(6153210, 'Ketu Dracotail', '计都星宿', '計都星辰', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组把1只「星辰」怪兽加入手卡。对方场上有怪兽存在的场合，可以再让以下效果适用。 ●自己的手卡·场上的怪兽作为融合素材，把1只龙族·魔法师族的融合怪兽融合召唤。'),
(62383431, 'Keurse, the Ogdoadic Light', '溟界之黄昏－凯泗', '溟界の黄昏－カース', 'Effect Monster', 'Reptile', 'LIGHT', 8, 400, 2400, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在墓地存在的场合，把自己场上1只怪兽解放才能发动。这张卡特殊召唤。那之后，对方可以从自身墓地选1只怪兽效果无效特殊召唤。 ②：这张卡特殊召唤成功的场合，以自己墓地1只4星以下的「溟界」怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽从场上离开的场合除外。'),
(65961304, 'Kewl Tune Back 2 Back', NULL, NULL, 'Synchro Tuner Monster', 'Fiend', 'DARK', 10, 3200, NULL, NULL),
(43904702, 'Kewl Tune Clip', '杀手旋律・酷莉普', 'キラーチューン・クリップ', 'Tuner Monster', 'Thunder', 'DARK', 2, 800, 1000, '场上的这张卡为素材作同调召唤的场合，手卡1只调整也能作为同调素材。这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在的场合，对方主要阶段才能发动。这张卡特殊召唤。那之后，可以进行1只同调怪兽调整的同调召唤。 ②：这张卡作为同调素材送去墓地的场合才能发动。对方的额外卡组的里侧的卡随机1张除外。'),
(39576656, 'Kewl Tune Crackle', NULL, NULL, 'Synchro Tuner Monster', 'Thunder', 'DARK', 5, 800, 2000, NULL),
(16387555, 'Kewl Tune Cue', '杀手旋律・绮悠', 'キラーチューン・キュー', 'Tuner Monster', 'Fairy', 'LIGHT', 3, 900, 1900, '场上的这张卡为素材作同调召唤的场合，手卡1只调整也能作为同调素材。这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤的场合才能发动。从自己的手卡·卡组·墓地把「杀手级调整曲·提示员」以外的1只调整特殊召唤。这个回合，自己不是调整不能特殊召唤。 ②：这张卡作为同调素材送去墓地的场合才能发动。从对方卡组上面把2张卡翻开，从那之中把1张除外，另1张回到卡组最上面或最下面。'),
(41069676, 'Kewl Tune Loudness War', '杀手旋律・响度战争', 'キラーチューン・ラウドネスウォー', 'Synchro Tuner Monster', 'Machine', 'LIGHT', 6, NULL, 3000, '调整＋调整1只以上 这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，自己场上的其他调整不会被效果破坏，对方不能把那些作为效果的对象。 ②：对方把效果发动时，从自己墓地把1只「杀手级调整曲」怪兽除外才能发动。除外的怪兽的自身作为同调素材送去墓地的场合发动的效果适用。'),
(16509007, 'Kewl Tune Mix', '杀手旋律・米可丝', 'キラーチューン・ミクス', 'Tuner Monster', 'Warrior', 'WIND', 2, 100, 2000, '场上的这张卡为素材作同调召唤的场合，手卡1只调整也能作为同调素材。这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从自己的卡组·墓地把2星怪兽以外的1只「杀手级调整曲」怪兽加入手卡。 ②：这张卡作为同调素材送去墓地的场合，以对方场上1只怪兽为对象才能发动。那只怪兽破坏。'),
(40847034, 'Kewl Tune Playlist', '杀手旋律・歌单', 'キラーチューン・プレイリスト', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合可以发动最多2张。 ①：以自己的场上·墓地1只「杀手级调整曲」怪兽为对象才能发动。以下效果各适用。这张卡的发动后，直到回合结束时自己不是调整不能特殊召唤。 ●作为对象的怪兽的自身作为同调素材送去墓地的场合发动的效果适用。 ●作为对象的怪兽回到手卡。'),
(89392810, 'Kewl Tune Reco', '杀手旋律・乐蔻', 'キラーチューン・レコ', 'Tuner Monster', 'Fiend', 'FIRE', 3, 1500, 800, '场上的这张卡为素材作同调召唤的场合，手卡1只调整也能作为同调素材。这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从自己的卡组·墓地把3星怪兽以外的1只「杀手级调整曲」怪兽加入手卡。 ②：这张卡作为同调素材送去墓地的场合，以对方场上1张魔法·陷阱卡为对象才能发动。那张卡破坏。'),
(88170262, 'Kewl Tune Remix', '杀手旋律・重混', 'キラーチューン・リミックス', 'Synchro Tuner Monster', 'Warrior', 'DARK', 5, 1500, 2000, '「杀手级调整曲·混音手」＋调整1只以上 这个卡名的②的效果1回合只能使用1次。 ①：只要对方的场上或墓地有调整存在，这张卡的攻击力上升1500。 ②：对方回合，把这张卡解放才能发动。从自己墓地选同调怪兽以外的2只调整，那之内的1只加入手卡，另1只特殊召唤。那之后，可以进行1只同调怪兽调整的同调召唤。'),
(17209452, 'Kewl Tune Rotary', NULL, NULL, 'Tuner Monster', 'Cyberse', 'LIGHT', 1, 100, 800, NULL),
(15665977, 'Kewl Tune RS', '杀手旋律・赤印', 'キラーチューン・レッドシール', 'Synchro Tuner Monster', 'Fiend', 'DARK', 5, 1700, 2400, '「杀手级调整曲·唱片师」＋调整1只以上 这个卡名的③的效果1回合只能使用1次。 ①：这张卡的攻击力上升双方墓地的调整数量×300。 ②：原本攻击力是1700以下的对方场上的怪兽的等级上升1星。 ③：自己·对方的主要阶段，从自己墓地把1只调整除外，以对方场上1张表侧表示卡为对象才能发动。那张卡的效果直到回合结束时无效。'),
(78058681, 'Kewl Tune Synchro', '杀手旋律・同步', 'キラーチューン・シンクロ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合可以发动最多2张。 ①：从卡组把「杀手级调整曲同调」以外的1张「杀手级调整曲」卡加入手卡。那之后，可以进行1只同调怪兽调整的同调召唤。这张卡的发动后，直到回合结束时自己不是调整不能特殊召唤。'),
(42781164, 'Kewl Tune Track Maker', '杀手旋律・造轨者', 'キラーチューン・トラックメイカー', 'Synchro Tuner Monster', 'Machine', 'LIGHT', 4, NULL, 2500, '「杀手级调整曲」调整＋调整1只以上 场上的这张卡为素材作同调召唤的场合，手卡1只调整也能作为同调素材。这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合才能发动。从卡组把1张「杀手级调整曲」卡加入手卡。 ②：这张卡作为同调素材送去墓地的场合才能发动。对方场上1张卡回到手卡。'),
(1929294, 'Key Mace', '钥梅思', 'キーメイス', 'Normal Monster', 'Fairy', 'LIGHT', 1, 400, 300, '非常细小的天使。无论是谁都被那可爱魅力折服而敞开心扉。'),
(20541432, 'Key Mace #2', '心锁妖精', 'ロックメイス', 'Normal Monster', 'Fiend', 'DARK', 4, 1050, 1200, '封印心中的良知，使对方成为恶魔的手下。'),
(23168060, 'Key Man the Key Warrior', '键战士', '鍵戦士キーマン', 'Effect Monster', 'Warrior', 'EARTH', 2, 1000, 500, '1回合1次，自己的主要阶段时才能发动。直到这个回合的结束阶段时，这张卡的等级变成3星。'),
(135598, 'Key Mouse', '钥匙鼠', 'キーマウス', 'Tuner Monster', 'Beast', 'EARTH', 1, 100, 100, '这张卡被战斗破坏送去墓地时，可以从自己卡组把1只3星以下的兽族怪兽加入手卡。'),
(72578374, 'Khaos Starsource Dragon', '空隙原星龙', '空隙の原星竜', 'Fusion Monster', 'Dragon', 'LIGHT', 8, 2500, 2500, '光·暗属性的龙族怪兽＋龙族怪兽 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡融合召唤的场合，以最多有那些作为融合素材的自己的光·暗属性怪兽数量的对方场上的卡为对象才能发动。那些卡破坏。 ②：这张卡被除外的场合，以自己场上1只光·暗属性的龙族·4星怪兽为对象才能发动。那只怪兽的等级变成8星。'),
(11501629, 'Kickfire', '踢火', 'キックファイア', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '只要这张卡在场上存在，每次自己场上表侧表示存在的炎属性怪兽被卡的效果破坏，那些破坏的怪兽数量的指示物给这张卡放置。这个效果1回合只能适用1次。此外，自己或者对方的准备阶段时把这张卡送去墓地才能发动。给与对方基本分这张卡的效果给这张卡放置的指示物数量×1000的数值的伤害。'),
(10759529, 'Kid Guard', '小子防御', 'キッズ・ガード', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上存在的1只「英雄小子」作为祭品。对方怪兽的攻击无效，从自己卡组把1只名字带有「元素英雄」的怪兽加入手卡。'),
(35629124, 'Kidmodo Dragon', '科多莫小龙', 'コドモドラゴン', 'Effect Monster', 'Dragon', 'EARTH', 3, 100, 200, '这个卡名的效果1回合只能使用1次，这个效果发动的回合，自己不是龙族怪兽不能特殊召唤，不能进行战斗阶段。 ①：这张卡被送去墓地的场合才能发动。从手卡把1只龙族怪兽特殊召唤。'),
(27240101, 'Kikinagashi Fucho', '耳边风鸟', 'キキナガシ風鳥', 'XYZ Monster', 'Winged Beast', 'WIND', 1, NULL, NULL, '1星怪兽×2 ①：这张卡只要在怪兽区域存在，不受其他卡的效果影响。 ②：1回合1次，把这张卡2个超量素材取除才能发动。这个回合，这张卡不会被战斗破坏，这张卡的战斗发生的对自己的战斗伤害变成0。这个效果在对方回合也能发动。'),
(88979991, 'Killer Needle', '杀手蜂', 'キラー・ビー', 'Normal Monster', 'Insect', 'WIND', 4, 1200, 1000, '巨大的黄蜂，攻击出乎意料的强，若被群体攻击则非常危险。'),
(63972571, 'King Beast Barbaros', '兽神王巴巴罗斯', '獣神王バルバロス', 'Effect Monster', 'Beast-Warrior', 'EARTH', 8, 3000, 1200, '这个卡名的①②的效果1回合各能使用1次。 ①：把等级合计直到8以上的自己场上的怪兽解放才能发动。这张卡从手卡特殊召唤。 ②：从自己墓地以及自己场上的表侧表示怪兽之中把1只「巴巴罗斯」怪兽除外，以对方场上2张卡为对象才能发动。那些卡破坏。 ③：这张卡可以向对方怪兽全部各作1次攻击。'),
(13756293, 'King Dragun', '龙魔人 龙骑士之王', '竜魔人 キングドラグーン', 'Fusion Monster', 'Dragon', 'DARK', 7, 2400, 1100, '「龙之支配者」＋「神龙 末日龙」 只要这张卡在场上表侧表示存在，对方不能指定龙族为魔法·陷阱·怪兽的效果的对象。1回合1次，可以从手卡特殊召唤1只龙族怪兽到自己场上。'),
(84686841, 'King Fog', '烟之王', 'キング・スモーク', 'Normal Monster', 'Fiend', 'DARK', 3, 1000, 900, '潜伏在烟雾中的恶魔，四周被浓烟包围，毫无踪迹可循。'),
(501000002, 'King of Destruction - Xexex', NULL, NULL, 'Effect Monster', 'Fiend', 'DARK', 10, 3000, 2500, NULL),
(4271596, 'King of the Ashened City', '灰灭之都的王', '灰滅せし都の王', 'Effect Monster', 'Pyro', 'DARK', 8, 1400, 2700, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：场地区域有「灰灭之都 奥布西地暮」存在的场合，这张卡可以从手卡特殊召唤。 ②：自己主要阶段才能发动。从手卡把「灰灭都之王」以外的1只「灰灭」怪兽特殊召唤。对方场上有攻击力2800以上的怪兽存在的场合，也能作为代替从卡组选。'),
(67757079, 'King of the Beasts', '毛兽之王', 'キング・オブ・ビースト', 'Effect Monster', 'Beast', 'EARTH', 7, 2500, 800, '可以把1只自己场上表侧表示存在的「毛扎」解放发动。这张卡从手卡或者墓地特殊召唤。「毛兽之王」在场上只能有1只表侧表示存在。'),
(11398059, 'King of the Feral Imps', '王者戈兰林', 'キングレムリン', 'XYZ Monster', 'Reptile', 'DARK', 4, 2300, 2000, '4星怪兽×2 ①：1回合1次，把这张卡1个超量素材取除才能发动。从卡组把1只爬虫类族怪兽加入手卡。'),
(36021814, 'King of the Skull Servants', '白骨王', 'ワイトキング', 'Effect Monster', 'Zombie', 'DARK', 1, -1, NULL, '①：这张卡的原本攻击力变成自己墓地的「白骨王」「白骨」数量×1000。 ②：这张卡被战斗破坏送去墓地时，从自己墓地把1只其他的「白骨王」或「白骨」除外才能发动。这张卡特殊召唤。'),
(79109599, 'King of the Swamp', '沼地魔神王', '沼地の魔神王', 'Effect Monster', 'Aqua', 'WATER', 3, 500, 1100, '①：融合怪兽融合召唤的场合，手卡·场上·墓地的这张卡可以作为那只融合怪兽有卡名记述的1只融合素材怪兽代用（其他的融合素材不能代用）。 ②：把这张卡从手卡丢弃去墓地才能发动。从卡组把1张「融合」加入手卡。'),
(69455834, 'King of Yamimakai', '暗魔界的霸王', '闇魔界の覇王', 'Normal Monster', 'Fiend', 'DARK', 5, 2000, 1530, '使用强大的暗之力量，破坏周围的一切。'),
(20438745, 'King Pyron', '灼热王 派隆', '灼熱王パイロン', 'Gemini Monster', 'Pyro', 'FIRE', 5, 1500, 500, '这张卡在墓地或者场上表侧表示存在的场合，当作通常怪兽使用。场上表侧表示存在的这张卡可以作当通常召唤使用的再度召唤，这张卡当作效果怪兽使用并得到以下效果。 ●可以给与对方基本分1000分伤害。这个效果1回合只能使用1次。'),
(60433216, 'King Scarlet', '绯色之王', 'キング・スカーレット', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：自己的「红莲魔」怪兽进行战斗的伤害计算时才能把这张卡发动。那只自己怪兽不会被那次战斗破坏，这张卡变成通常怪兽（恶魔族·调整·炎·1星·攻/守0）在怪兽区域特殊召唤。这张卡也当作陷阱卡使用。'),
(83986578, 'King Tiger Wanghu', '王虎', '王虎ワンフー', 'Effect Monster', 'Beast', 'EARTH', 4, 1700, 1000, '①：这张卡已在怪兽区域存在的状态，每次攻击力1400以下的怪兽召唤·特殊召唤发动。这张卡在场上表侧表示存在的场合，那些攻击力1400以下的怪兽破坏。'),
(24590232, 'King''s Consonance', '王魂调和', '王魂調和', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方怪兽的直接攻击宣言时才能发动。那次攻击无效。那之后，以下效果可以适用。 ●等级合计最多到8以下为止，从自己墓地选调整1只和调整以外的怪兽任意数量除外，把持有和除外的怪兽的等级合计相同等级的1只同调怪兽从额外卡组当作同调召唤作特殊召唤。'),
(64788463, 'King''s Knight', '国王骑士', 'キングス・ナイト', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1600, 1400, '①：自己场上有「王后骑士」存在，这张卡召唤成功时才能发动。从卡组把1只「卫兵骑士」特殊召唤。'),
(16528181, 'King''s Sarcophagus', '王之棺', '王の棺', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合可以使用最多4次。 ①：只要这张卡在魔法与陷阱区域存在，自己场上的「荷鲁斯」怪兽不会被不以自身为对象的卡的效果破坏。 ②：把1张手卡送去墓地才能发动。从卡组把1只「荷鲁斯」怪兽送去墓地。 ③：1回合1次，自己的「荷鲁斯」怪兽和对方怪兽进行战斗的伤害步骤开始时才能发动。那只对方怪兽送去墓地。'),
(27503418, 'King''s Synchro', '王者之同步', '王者の調和', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方怪兽向自己的同调怪兽攻击宣言时才能发动。那次攻击无效。那之后，以下效果可以适用。 ●那只自己的同调怪兽和自己墓地1只调整除外，把持有和除外的怪兽的等级合计相同等级的1只同调怪兽从额外卡组当作同调召唤作特殊召唤。'),
(9251497, 'Kingyo Sukui', '救金鱼', '金魚救い', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：以对方墓地1只怪兽为对象才能发动。自己卡组最上面的卡翻开。翻开的卡是持有和作为对象的怪兽相同属性的怪兽的场合，翻开的卡加入手卡，作为对象的怪兽回到对方卡组。不是的场合，翻开的卡送去墓地，这张卡破坏。'),
(45452224, 'Kinka-byo', '金华猫', '金華猫', 'Spirit Monster', 'Beast', 'DARK', 1, 400, 200, '这张卡不能特殊召唤。 ①：这张卡召唤·反转时，以自己墓地1只1星怪兽为对象才能发动。那只怪兽特殊召唤。这张卡从场上离开时那只怪兽除外。 ②：这张卡召唤·反转的回合的结束阶段发动。这张卡回到持有者手卡。'),
(84814897, 'Kiryu', '骑龙', '騎竜', 'Union Effect Monster', 'Dragon', 'DARK', 5, 2000, 1500, '1回合只有1次在自己的主要阶段可以当作装备卡使用给自己的「暗魔界的战士 暗黑之剑」装备，或者把装备解除以表侧攻击表示特殊召唤。只在这个效果当作装备卡使用时，装备怪兽的攻击力·守备力上升900点。可以把装备状态的这张卡作为祭品，装备怪兽在这个回合可以直接攻击对方玩家。（1只怪兽可以装备的同盟最多1张。装备怪兽被战斗破坏的场合，作为代替把这张卡破坏。）'),
(4266839, 'Kiseitai', '精神寄生体', '精神寄生体', 'Effect Monster', 'Fiend', 'DARK', 2, 300, 800, '场上里侧守备表示存在的这张卡被对方怪兽攻击的场合，那次伤害计算前这张卡变成攻击怪兽的装备卡。每次对方的准备阶段，自己基本分回复这张卡的装备怪兽的攻击力一半的数值。'),
(60519422, 'Kishido Spirit', '骑士道精神', '騎士道精神', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '自己场上的怪兽和攻击力相同的怪兽战斗时不会被破坏。'),
(16960120, 'Kitchen Dragonmaid', '龙女仆・炊事龙女', 'ドラゴンメイド・ティルル', 'Effect Monster', 'Dragon', 'FIRE', 3, 500, 1700, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组把「半龙女仆·蒸馏室龙女」以外的1只「半龙女仆」怪兽加入手卡。那之后，从手卡选1只「半龙女仆」怪兽送去墓地。 ②：自己·对方的战斗阶段开始时才能发动。这张卡回到手卡，从自己的手卡·墓地把1只8星「半龙女仆」怪兽特殊召唤。'),
(3361010, 'Kitsuni Kitsunebi', '愉怪之磷的狐火摇', '愉怪な燐のきつねびゆらら', 'Effect Monster', 'Warrior', 'FIRE', 3, 200, 1900, '这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，场上的表侧表示怪兽变成炎属性。 ②：这张卡在墓地存在，对方的场上或者墓地有炎属性怪兽存在的场合才能发动。这张卡特殊召唤。'),
(64475743, 'Kittytail, Mystical Beast of the Forest', '森之圣兽 红毛苋小猫', '森の聖獣 キティテール', 'Effect Monster', 'Beast', 'EARTH', 2, 200, 200, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合，以自己墓地1只兽族·兽战士族·鸟兽族·昆虫族·植物族怪兽为对象才能发动。原本种族和那只怪兽相同的1只怪兽从卡组送去墓地。 ②：这张卡被对方破坏的场合才能发动。从卡组把「森之圣兽 红毛苋小猫」以外的1只兽族·兽战士族·鸟兽族·昆虫族·植物族怪兽加入手卡。'),
(82627406, 'Kiwi Magician Girl', '奇异果魔术少女', 'キウイ・マジシャン・ガール', 'Effect Monster', 'Spellcaster', 'WIND', 5, 1800, 1200, '①：把这张卡从手卡丢弃才能发动。自己场上的「魔术少女」怪兽的攻击力·守备力直到回合结束时上升双方的场上·墓地的「魔术少女」怪兽种类×300。这个效果在对方回合也能发动。 ②：只要这张卡在怪兽区域存在，自己场上的魔法师族怪兽不会被效果破坏，不会成为对方的效果的对象。'),
(98007437, 'Knight Armed Dragon, the Armored Knight Dragon', '铠骑士龙－剑侍武装龙－', '鎧騎士竜－ナイト・アームド・ドラゴン－', 'Effect Monster', 'Dragon', 'WIND', 3, 1400, 1900, '这个卡名的①②③的效果1回合各能使用1次。 ①：自己把5星以上的龙族怪兽特殊召唤的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡特殊召唤的场合才能发动。这张卡的属性·等级变成和自己的除外状态的1只龙族怪兽相同。 ③：这张卡被送去墓地的场合，以自己场上1只龙族怪兽为对象才能发动（双方不能对应这个效果的发动把效果发动）。那只怪兽的攻击力上升1000。'),
(15767889, 'Knight Day Grepher', '骑士 迪·格雷法', '騎士デイ・グレファー', 'Gemini Monster', 'Warrior', 'LIGHT', 4, 1700, 1600, '①：这张卡只要在场上·墓地存在，当作通常怪兽使用。 ②：可以把场上的当作通常怪兽使用的这张卡作为通常召唤作再1次召唤。那个场合这张卡变成当作效果怪兽使用并得到以下效果。 ●自己结束阶段，以自己墓地1张装备魔法卡为对象才能发动。那张卡加入手卡。这个卡名的这个效果1回合只能使用1次。'),
(75901113, 'Knight of Armor Dragon', '铠龙圣骑', '鎧竜の聖騎士', 'Ritual Effect Monster', 'Dragon', 'WIND', 4, 1900, 1200, '「铠龙降临」降临。这个卡名的①②的效果1回合各能使用1次。 ①：从额外卡组特殊召唤的怪兽和这张卡进行战斗的伤害步骤开始时才能发动。那只怪兽回到持有者卡组。 ②：把这张卡解放才能发动。从手卡·卡组把1只5星以上的龙族·风属性怪兽特殊召唤。'),
(300204002, 'Knight of Legend', NULL, NULL, 'Skill Card', 'Yami Yugi', NULL, NULL, NULL, NULL, NULL),
(46237548, 'Knight of the Red Lotus', '红莲魔斗士', '紅蓮魔闘士', 'Effect Monster', 'Warrior', 'FIRE', 6, 2100, 1800, '①：这张卡可以在自己墓地的通常怪兽是3只的场合，把那之内的2只除外，从手卡特殊召唤。 ②：1回合1次，以自己墓地1只4星以下的通常怪兽为对象才能发动。那只怪兽特殊召唤。'),
(87210505, 'Knight''s Title', '骑士的称号', '騎士の称号', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：把自己场上1只表侧表示的「黑魔术师」解放才能发动。从自己的手卡·卡组·墓地选1只「黑魔术骑士」特殊召唤。'),
(75452921, 'Knightmare Cerberus', '梦魇曲・地狱犬', 'トロイメア・ケルベロス', 'Link Monster', 'Fiend', 'EARTH', NULL, 1600, NULL, '卡名不同的怪兽2只 这个卡名的①的效果1回合只能使用1次。 ①：这张卡连接召唤的场合，丢弃1张手卡，以对方的主要怪兽区域1只特殊召唤的怪兽为对象才能发动。那只怪兽破坏。这个效果的发动时这张卡是互相连接状态的场合，再让自己可以抽1张。 ②：只要这张卡在怪兽区域存在，自己场上的互相连接状态的怪兽不会被效果破坏。'),
(10158145, 'Knightmare Corruptor Iblee', '梦魇曲 崩界之伊布丽丝', '夢幻崩界イヴリース', 'Effect Monster', 'Cyberse', 'DARK', 2, NULL, NULL, '这个卡名的③的效果1回合只能使用1次。 ①：这张卡召唤成功时，以自己墓地1只连接怪兽为对象才能发动。那只怪兽的攻击力变成0，效果无效，在要和这张卡成为连接状态的自己场上特殊召唤。 ②：只要这张卡在怪兽区域存在，这张卡的控制者不是连接怪兽不能特殊召唤。 ③：这张卡从自己场上送去墓地的场合才能发动。这张卡在对方场上守备表示特殊召唤。'),
(39064822, 'Knightmare Goblin', '梦魇曲・格布林', 'トロイメア・ゴブリン', 'Link Monster', 'Fiend', 'WIND', NULL, 1300, NULL, '卡名不同的怪兽2只 ①：这张卡在自己回合连接召唤的场合，丢弃1张手卡才能发动。这个效果的发动时这张卡是互相连接状态的场合，自己可以抽1张。这个回合，自己在通常召唤外加上只有1次，自己主要阶段可以从手卡把1只怪兽在作为这张卡所连接区的自己场上召唤。 ②：只要这张卡在怪兽区域存在，双方不能把自己场上的互相连接状态的怪兽作为效果的对象。'),
(65330383, 'Knightmare Gryphon', '梦魇曲・鹰头狮', 'トロイメア・グリフォン', 'Link Monster', 'Fiend', 'LIGHT', NULL, 2500, NULL, '卡名不同的怪兽2只以上 这个卡名的①的效果1回合只能使用1次。 ①：这张卡连接召唤的场合，丢弃1张手卡，以自己墓地1张魔法·陷阱卡为对象才能发动。那张卡在自己场上盖放。这个效果盖放的卡在这个回合不能发动。这个效果的发动时这张卡是互相连接状态的场合，再让自己可以抽1张。 ②：只要这张卡在怪兽区域存在，双方不能把不在连接状态的特殊召唤的场上的怪兽的效果发动。'),
(9794980, 'Knightmare Incarnation Idlee', '梦魇曲 转星之伊德丽丝', '夢幻転星イドリース', 'Effect Monster', 'Fairy', 'DARK', 9, 2100, 2100, '这个卡名的①②的效果1回合各能使用1次。 ①：场上的连接怪兽的连接标记合计是8以上的场合才能发动。这张卡从手卡特殊召唤。这个效果在对方回合也能发动。 ②：对方场上的连接怪兽数量比自己场上的连接怪兽多的状态，这张卡特殊召唤成功的场合才能发动。场上的连接怪兽全部送去墓地。 ③：自己场上的9星怪兽不会被效果破坏。'),
(3679218, 'Knightmare Mermaid', '梦魇曲・美人鱼', 'トロイメア・マーメイド', 'Link Monster', 'Fiend', 'WATER', NULL, 1000, NULL, '「梦幻崩影·人鱼」以外的「幻崩」怪兽1只 这个卡名的①的效果1回合只能使用1次。 ①：这张卡连接召唤成功的场合，丢弃1张手卡才能发动。从卡组把1只「幻崩」怪兽特殊召唤。这个效果的发动时这张卡是互相连接状态的场合，再让自己可以从卡组抽1张。 ②：只要这张卡在怪兽区域存在，场上的不在互相连接状态的怪兽的攻击力·守备力下降1000。'),
(2857636, 'Knightmare Phoenix', '梦魇曲・不死鸟', 'トロイメア・フェニックス', 'Link Monster', 'Fiend', 'FIRE', NULL, 1900, NULL, '卡名不同的怪兽2只 这个卡名的①的效果1回合只能使用1次。 ①：这张卡连接召唤的场合，丢弃1张手卡，以对方场上1张魔法·陷阱卡为对象才能发动。那张卡破坏。这个效果的发动时这张卡是互相连接状态的场合，再让自己可以抽1张。 ②：只要这张卡在怪兽区域存在，互相连接状态的自己怪兽不会被战斗破坏。'),
(38342335, 'Knightmare Unicorn', '梦魇曲・独角兽', 'トロイメア・ユニコーン', 'Link Monster', 'Fiend', 'DARK', NULL, 2200, NULL, '卡名不同的怪兽2只以上 这个卡名的①的效果1回合只能使用1次。 ①：这张卡连接召唤的场合，丢弃1张手卡，以场上1张卡为对象才能发动。那张卡回到卡组。这个效果的发动时这张卡是互相连接状态的场合，再让自己可以抽1张。 ②：只要互相连接状态的「幻崩」怪兽存在，自己抽卡阶段的通常抽卡数量变成那些「幻崩」怪兽种类的数量。'),
(39037517, 'Koa''ki Meiru Beetle', '核成甲虫', 'コアキメイル・ビートル', 'Effect Monster', 'Insect', 'EARTH', 4, 1900, 1500, '这张卡的控制者在每次自己的结束阶段从手卡把1张「核成兽的钢核」送去墓地或把手卡1只昆虫族怪兽给对方观看。或者都不进行让这张卡破坏。光属性或者暗属性怪兽表侧攻击表示特殊召唤成功时，那些怪兽变成守备表示。'),
(80367387, 'Koa''ki Meiru Bergzak', '核成双刀手', 'コアキメイル・ベルグザーク', 'Effect Monster', 'Warrior', 'EARTH', 4, 2000, 200, '这张卡的控制者在每次自己的结束阶段从手卡把1张「核成兽的钢核」送去墓地或把手卡1只战士族怪兽给对方观看。或者都不进行让这张卡破坏。这张卡战斗破坏对方怪兽的场合，只有1次可以继续攻击。'),
(6320631, 'Koa''ki Meiru Boulder', '核成岩人', 'コアキメイル・ロック', 'Effect Monster', 'Rock', 'EARTH', 4, 1200, 1000, '这张卡被战斗破坏送去墓地时，可以从自己卡组把1张「核成兽的钢核」或者1只4星以下的名字带有「核成」的怪兽加入手卡。'),
(32314730, 'Koa''ki Meiru Crusader', '核成十字军', 'コアキメイル・クルセイダー', 'Effect Monster', 'Beast-Warrior', 'EARTH', 4, 1900, 1300, '这张卡的控制者在每次自己的结束阶段从手卡把1张「核成兽的钢核」送去墓地或把手卡1只兽战士族怪兽给对方观看。或者都不进行让这张卡破坏。这张卡战斗破坏对方怪兽的场合，可以把自己墓地存在的1张名字带有「核成」的卡加入手卡。'),
(80925836, 'Koa''ki Meiru Doom', '核成恶魔', 'コアキメイル・デビル', 'Effect Monster', 'Fiend', 'WIND', 3, 1700, 800, '这张卡的控制者在每次自己的结束阶段从手卡把1张「核成兽的钢核」送去墓地或把手卡1只恶魔族怪兽给对方观看。或者都不进行让这张卡破坏。只要这张卡在自己场上表侧表示存在，主要阶段时发动的光属性以及暗属性的效果怪兽的效果无效化。'),
(12435193, 'Koa''ki Meiru Drago', '核成龙', 'コアキメイル・ドラゴ', 'Effect Monster', 'Dragon', 'WIND', 4, 1900, 1600, '这张卡的控制者在每次自己结束阶段从手卡把1张「核成兽的钢核」送去墓地或把手卡1只龙族怪兽给对方观看。或者都不进行让这张卡破坏。 ①：只要这张卡在怪兽区域存在，双方不能把光·暗属性怪兽特殊召唤。'),
(5817857, 'Koa''ki Meiru Ghoulungulate', '核成食尸奴', 'コアキメイル・グールズスレイブ', 'Effect Monster', 'Zombie', 'EARTH', 5, 2500, 1700, '这张卡的控制者在每次自己的结束阶段从手卡把1张「核成兽的钢核」送去墓地或把手卡1只不死族怪兽给对方观看。或者都不进行让这张卡破坏。自己场上存在的名字带有「核成」的怪兽1只被战斗或者卡的效果破坏的场合，可以作为代替把自己墓地存在的1只名字带有「核成」的怪兽从游戏中除外。'),
(41201555, 'Koa''ki Meiru Gravirose', '核成孕妇蔷薇', 'コアキメイル・グラヴィローズ', 'Effect Monster', 'Plant', 'FIRE', 4, 1900, 1300, '这张卡的控制者在每次自己的结束阶段从手卡把1张「核成兽的钢核」送去墓地或把手卡1只植物族怪兽给对方观看。或者都不进行让这张卡破坏。自己的准备阶段时只有1次，可以从自己卡组把1只3星以下的怪兽送去墓地。'),
(45041488, 'Koa''ki Meiru Guardian', '核成・守护者', 'コアキメイル・ガーディアン', 'Effect Monster', 'Rock', 'EARTH', 4, 1900, 1200, '这张卡的控制者在每次自己的结束阶段从手卡把1张「核成兽的钢核」送去墓地或把手卡1只岩石族怪兽给对方观看。或者都不进行让这张卡破坏。效果怪兽的效果发动时，可以把这张卡解放让那个发动无效并破坏。'),
(31692182, 'Koa''ki Meiru Hydro Barrier', '核成全护者', 'コアキメイル・フルバリア', 'Effect Monster', 'Aqua', 'WATER', 3, 1000, 1900, '从手卡让1张「核成兽的钢核」回到卡组最上面发动。直到下次的自己回合的准备阶段时，名字带有「核成」的怪兽以外的场上表侧表示存在的效果怪兽的效果无效化。'),
(54520292, 'Koa''ki Meiru Ice', '核成冰人', 'コアキメイル・アイス', 'Effect Monster', 'Aqua', 'WATER', 4, 1900, 1200, '这张卡的控制者在每次自己的结束阶段从手卡把1张「核成兽的钢核」送去墓地或把手卡1张永续魔法卡给对方观看。或者都不进行让这张卡破坏。可以把1张手卡送去墓地让场上存在的1只特殊召唤的怪兽破坏。'),
(91985515, 'Koa''ki Meiru Initialize!', '钢核初期化', '鋼核初期化', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '把自己场上存在的1只名字带有「核成」的怪兽解放发动。从自己的卡组·墓地把1张「核成兽的钢核」加入手卡。'),
(65026212, 'Koa''ki Meiru Maximus', '核成巨龙', 'コアキメイル・マキシマム', 'Effect Monster', 'Dragon', 'WIND', 8, 3000, 2500, '这张卡不能通常召唤。从自己手卡把1张「核成兽的钢核」从游戏中除外的场合可以特殊召唤。这张卡的控制者在每次自己的结束阶段从手卡把1张「核成兽的钢核」或1只名字带有「核成」的怪兽送去墓地。或者都不进行让这张卡破坏。1回合1次，自己的主要阶段时可以选择对方场上存在的1张卡破坏。'),
(14309486, 'Koa''ki Meiru Overload', '核成过量体', 'コアキメイル・オーバードーズ', 'Effect Monster', 'Rock', 'EARTH', 4, 1900, 1200, '这张卡的控制者在每次自己结束阶段从手卡把1张「核成兽的钢核」送去墓地或把手卡1只岩石族怪兽给对方观看。或者都不进行让这张卡破坏。 ①：对方把怪兽召唤·反转召唤·特殊召唤之际，把这张卡解放才能发动。那个无效，那些怪兽破坏。'),
(19642889, 'Koa''ki Meiru Powerhand', '核成电钻手', 'コアキメイル・パワーハンド', 'Effect Monster', 'Machine', 'EARTH', 4, 2100, 1600, '这张卡的控制者在每次自己的结束阶段从手卡把1张「核成兽的钢核」送去墓地或把手卡1张通常陷阱卡给对方观看。或者都不进行让这张卡破坏。这张卡和光属性或者暗属性怪兽进行战斗的场合，只在战斗阶段内那只怪兽的效果无效化。'),
(176392, 'Koa''ki Meiru Prototype', '核成试验台', 'コアキメイル・テストベッド', 'Effect Monster', 'Rock', 'EARTH', 4, 1800, 1800, '场上表侧表示存在的名字带有「核成」的怪兽在结束阶段时被破坏的场合，可以作为代替把这张卡破坏。此外，场上表侧表示存在的名字带有「核成」的怪兽在结束阶段时被破坏时，可以在自己场上把1只「核成衍生物」（岩石族·地·4星·攻/守1800）特殊召唤。'),
(10060427, 'Koa''ki Meiru Rooklord', '核成城主', 'コアキメイル・ルークロード', 'Effect Monster', 'Warrior', 'EARTH', 7, 2800, 2200, '这张卡的控制者在每次自己的结束阶段从手卡把1张「核成兽的钢核」送去墓地或把手卡1只战士族怪兽给对方观看。或者都不进行让这张卡破坏。这张卡可以把1只名字带有「核成」的怪兽解放作上级召唤。这张卡召唤成功时，可以把自己墓地存在的1张名字带有「核成」的卡从游戏中除外，对方场上存在的最多2张卡破坏。'),
(49680980, 'Koa''ki Meiru Sandman', '核成沙人', 'コアキメイル・サンドマン', 'Effect Monster', 'Rock', 'EARTH', 4, 1900, 1200, '这张卡的控制者在每次自己的结束阶段从手卡把1张「核成兽的钢核」送去墓地或把手卡1只岩石族怪兽给对方观看。或者都不进行让这张卡破坏。对方的陷阱卡发动时，可以把这张卡解放让那个发动无效并破坏。'),
(74576482, 'Koa''ki Meiru Sea Panther', '核成海豹', 'コアキメイル・シーパンサー', 'Effect Monster', 'Sea Serpent', 'WATER', 4, 1900, 1200, '这张卡的控制者在每次自己的结束阶段从手卡把1张「核成兽的钢核」送去墓地或把手卡1只水属性怪兽给对方观看。或者都不进行让这张卡破坏。1回合1次，可以从手卡把1张「核成兽的钢核」送去墓地，选择自己墓地存在的1张魔法卡回到卡组最上面。'),
(12216615, 'Koa''ki Meiru Shield', '核成兽的障壁', 'コアキメイルの障壁', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己墓地有「核成兽的钢核」2张以上存在的场合，对方怪兽的攻击宣言时才能发动。对方场上表侧攻击表示存在的怪兽全部破坏。'),
(68809475, 'Koa''ki Meiru Speeder', '核成高速鸟', 'コアキメイル・スピード', 'Effect Monster', 'Machine', 'WIND', 3, 1200, 2200, '这张卡的控制者在每次自己的结束阶段从手卡把1张「核成兽的钢核」送去墓地或把手卡1只机械族怪兽给对方观看。或者都不进行让这张卡破坏。只要这张卡在场上表侧表示存在，自己的抽卡阶段时抽到的卡是「核成兽的钢核」的场合，可以把那张卡给对方观看让自己再抽1张卡。'),
(80839052, 'Koa''ki Meiru Supplier', '核成・供给者', 'コアキメイル・サプライヤー', 'Effect Monster', 'Rock', 'EARTH', 4, 1400, 1600, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上的表侧表示的岩石族怪兽被送去墓地的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡特殊召唤成功的场合才能发动。从卡组把1张「核成供给者」以外的有「核成兽的钢核」的卡名记述的卡或者「核成兽的钢核」加入手卡。'),
(176393, 'Koa''ki Meiru Token', '核成试验台', 'コアキメイル・テストベッド', 'Token', 'Rock', NULL, NULL, NULL, NULL, NULL),
(95204084, 'Koa''ki Meiru Tornado', '核成风神', 'コアキメイル・トルネード', 'Effect Monster', 'Winged Beast', 'WIND', 4, 1500, 1200, '从手卡让1张「核成兽的钢核」回到卡组最上面发动。对方场上存在的特殊召唤的怪兽全部破坏。'),
(30936186, 'Koa''ki Meiru Urnight', '核成原始骑士', 'コアキメイル・ウルナイト', 'Effect Monster', 'Beast-Warrior', 'EARTH', 4, 2000, 1500, '这张卡的控制者在每次自己的结束阶段从手卡把1张「核成兽的钢核」送去墓地或把手卡1只兽战士族怪兽给对方观看。或者都不进行让这张卡破坏。1回合1次，可以把手卡1张「核成兽的钢核」给对方观看，从自己卡组把「核成原始骑士」以外的1只4星以下的名字带有「核成」的怪兽特殊召唤。'),
(72258771, 'Koa''ki Meiru Valafar', '核成魔神 华拉法', 'コアキメイル・ヴァラファール', 'Effect Monster', 'Fiend', 'FIRE', 8, 3000, 2100, '这张卡的控制者在每次自己的结束阶段从手卡把1张「核成兽的钢核」送去墓地。或者不送去墓地让这张卡破坏。这张卡可以把1只名字带有「核成」的怪兽解放作上级召唤。这张卡攻击守备表示怪兽时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。这张卡不会被陷阱卡的效果破坏。'),
(66816282, 'Koa''ki Meiru Wall', '核成墙人', 'コアキメイル・ウォール', 'Effect Monster', 'Rock', 'EARTH', 4, 1900, 1200, '这张卡的控制者在每次自己的结束阶段从手卡把1张「核成兽的钢核」送去墓地或把手卡1只岩石族怪兽给对方观看。或者都不进行让这张卡破坏。对方的魔法卡发动时，可以把这张卡解放让那个发动无效并破坏。'),
(95090813, 'Koa''ki Meiru War Arms', '核成战甲兵', 'コアキメイル・ウォーアームズ', 'Effect Monster', 'Warrior', 'EARTH', 4, 1400, 1200, '这张卡的控制者在每次自己的结束阶段从手卡把1张「核成兽的钢核」送去墓地或把手卡1只战士族怪兽给对方观看。或者都不进行让这张卡破坏。1回合1次，可以选择自己墓地存在的1只等级3以下的战士族怪兽装备在这张卡上。这张卡的攻击力上升由这个效果装备的怪兽卡攻击力总和的一半。若这张卡被战斗破坏，作为代替把全部由这个效果装备的怪兽卡破坏。'),
(46089249, 'Koa''ki Ring', '核杀轮', 'コアキリング', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '把手卡1张「核成兽的钢核」给对方观看发动。把场上表侧表示存在的1只怪兽破坏，双方受到1000分伤害。'),
(7243511, 'Koalo-Koala', '考拉考拉', 'コアラッコアラ', 'Fusion Monster', 'Beast', 'EARTH', 6, 2800, 200, '「树熊海獭」＋「海獭树熊」 从手卡把1只兽族怪兽送去墓地，选择对方场上存在的1只怪兽发动。选择的怪兽破坏。'),
(55359571, 'Kochobo''s Hinamatsuri', '千灵偶的雏人形祭', 'こちょぼの人形祀り', 'Effect Monster', 'Machine', 'DARK', 7, 2200, 2200, '这个卡名的效果1回合只能使用1次。 ①：这张卡在手卡·墓地存在的场合，以场上1只机械族怪兽为对象才能发动。这张卡特殊召唤，作为对象的怪兽的攻击力变成一半。这个效果特殊召唤的这张卡等级变成和作为对象的怪兽相同，从场上离开的场合除外。这个效果的发动后，直到回合结束时自己不是超量怪兽不能从额外卡组特殊召唤。'),
(69456283, 'Koitsu', '此者', 'コイツ', 'Union Effect Monster', 'Fairy', 'WATER', 10, 200, 100, '1回合只有1次，在自己的主要阶段，场上的这张卡可以当作装备卡使用给「彼者」装备，或者把装备解除以表侧攻击表示特殊召唤。装备怪兽的攻击力上升3000点。装备怪兽攻击守备表示的怪兽时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。（1只怪兽可以装备的同盟最多1张，装备怪兽被战斗破坏的场合，作为代替把这张卡破坏。）'),
(1184620, 'Kojikocy', '魔物狩人', '魔物の狩人', 'Normal Monster', 'Warrior', 'EARTH', 4, 1500, 1200, '猎杀人类的猎手，具有连岩石都能击碎的力量。'),
(57722593, 'Konohanasakuya', '木花开耶', '木花咲弥', 'Spirit Monster', 'Fairy', 'EARTH', 3, 1300, 1300, '这张卡不能通常召唤。自己场上有灵魂怪兽存在的场合才能特殊召唤。这个方法的「木花咲弥」的特殊召唤1回合只能有1次。 ①：这张卡特殊召唤的回合的结束阶段发动。这张卡回到持有者手卡。 ②：自己·对方的结束阶段，把墓地的这张卡除外，以自己场上1只灵魂怪兽为对象才能发动。这个回合，那只表侧表示怪兽不能把场上发动的效果发动。'),
(32569498, 'Korogashi', '屎壳郎', 'コロガーシ', 'Normal Monster', 'Insect', 'EARTH', 2, 550, 400, '可以推动比自己身体大几倍的粪便，压倒对方。'),
(19406822, 'Kotodama', '言灵', 'コトダマ', 'Effect Monster', 'Fairy', 'EARTH', 3, NULL, 1600, '只要这张卡在场上表侧表示存在，同名怪兽不能在场上表侧表示存在并破坏。之后召唤·特殊召唤·反转的同名怪兽破坏（同时的场合，同名怪兽全部破坏）。'),
(67724379, 'Koumori Dragon', '恶魔龙', 'デビル・ドラゴン', 'Normal Monster', 'Dragon', 'DARK', 4, 1500, 1200, '凶恶的龙。吐出邪恶的火焰使人变得邪恶。'),
(99171160, 'Kozaky', '平庸鬼', 'コザッキー', 'Normal Monster', 'Fiend', 'DARK', 1, 400, 400, '奉献一切研究魔界语言的凶猛恶魔。由于工作过度而精神崩溃。'),
(21908319, 'Kozaky''s Self-Destruct Button', '平庸鬼的自爆装置', 'コザッキーの自爆装置', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '给与破坏盖放的这张卡的玩家1000分伤害。'),
(55885348, 'Kozmo Dark Destroyer', '星际仙踪-达克大弯刀号', 'Kozmo－ダークシミター', 'Effect Monster', 'Machine', 'DARK', 8, 3000, 1800, '①：这张卡召唤·特殊召唤成功的场合，以场上1只怪兽为对象才能发动。那只怪兽破坏。 ②：这张卡不会成为对方的效果的对象。 ③：这张卡被战斗·效果破坏送去墓地的场合，把墓地的这张卡除外才能发动。从卡组把1只7星以下的「星际仙踪」怪兽特殊召唤。'),
(64063868, 'Kozmo Dark Eclipser', '星际仙踪-达克日食者号', 'Kozmo－ダークエクリプサー', 'Effect Monster', 'Machine', 'DARK', 9, 3000, 2600, '①：这张卡不会成为对方的效果的对象。 ②：陷阱卡发动时，从自己墓地把1只「星际仙踪」怪兽除外才能发动。那个发动无效并破坏。 ③：这张卡被战斗·效果破坏送去墓地的场合，把墓地的这张卡除外才能发动。从卡组把1只8星以下的「星际仙踪」怪兽加入手卡。'),
(85991529, 'Kozmo Dark Planet', '星际仙踪-达克星', 'Kozmo－ダークプラネット', 'Effect Monster', 'Machine', 'DARK', 10, 4000, 4000, '这张卡不能通常召唤。把等级合计直到10以上的手卡的「星际仙踪」怪兽除外的场合才能特殊召唤。 ①：这张卡不会成为对方的效果的对象。 ②：魔法卡发动时，从自己墓地把1只「星际仙踪」怪兽除外才能发动。那个发动无效并破坏。 ③：这张卡被战斗·效果破坏送去墓地的场合，把墓地的这张卡除外才能发动。从卡组把1只9星以下的「星际仙踪」怪兽加入手卡。'),
(37679169, 'Kozmo Delta Shuttle', '星际仙踪-德尔塔穿梭机', 'Kozmo－デルタシャトル', 'Effect Monster', 'Machine', 'DARK', 5, 2000, 2000, '①：1回合1次，从卡组把1只「星际仙踪」怪兽送去墓地，以场上1只表侧表示怪兽为对象才能发动。作为对象的怪兽的攻击力·守备力下降因为这个效果发动而送去墓地的怪兽的等级×100。 ②：这张卡被战斗·效果破坏送去墓地的场合，把墓地的这张卡除外才能发动。从卡组把1只4星以下的「星际仙踪」怪兽特殊召唤。'),
(29491334, 'Kozmo DOG Fighter', '星际仙踪-DOG战斗机', 'Kozmo－ドッグファイター', 'Effect Monster', 'Machine', 'DARK', 6, 2000, 2400, '①：自己·对方的准备阶段才能发动。在自己场上把1只「DOG战斗机衍生物」（机械族·暗·6星·攻2000/守2400）特殊召唤。 ②：这张卡被战斗·效果破坏送去墓地的场合，把墓地的这张卡除外才能发动。从卡组把1只5星以下的「星际仙踪」怪兽特殊召唤。'),
(31061682, 'Kozmo Farmgirl', '星际仙踪-多萝塞尔', 'Kozmo－ドロッセル', 'Effect Monster', 'Psychic', 'LIGHT', 3, 1500, 1000, '「星际仙踪-多萝塞尔」的①的效果1回合只能使用1次。 ①：把场上的这张卡除外才能发动。从手卡把1只4星以上的「星际仙踪」怪兽特殊召唤。这个效果在对方回合也能发动。 ②：这张卡给与对方战斗伤害时，支付500基本分才能发动。从卡组把1张「星际仙踪」卡加入手卡。'),
(20849090, 'Kozmo Forerunner', '星际仙踪-先行者号', 'Kozmo－フォアランナー', 'Effect Monster', 'Machine', 'LIGHT', 7, 2800, 1400, '①：这张卡不会成为对方的效果的对象。 ②：自己准备阶段发动。自己回复1000基本分。 ③：这张卡被战斗·效果破坏送去墓地的场合，把墓地的这张卡除外才能发动。从卡组把1只6星以下的「星际仙踪」怪兽特殊召唤。'),
(67050396, 'Kozmo Goodwitch', '星际仙踪-格琳德尔', 'Kozmo－グリンドル', 'Effect Monster', 'Psychic', 'LIGHT', 4, 1800, 1000, '「星际仙踪-格琳德尔」的①的效果1回合只能使用1次。 ①：把场上的这张卡除外才能发动。从手卡把1只5星以上的「星际仙踪」怪兽特殊召唤。这个效果在对方回合也能发动。 ②：1回合1次，支付500基本分，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽变成里侧守备表示。'),
(59496924, 'Kozmo Landwalker', '星际仙踪-陆地步行机', 'Kozmo－ランドウォーカー', 'Effect Monster', 'Machine', 'DARK', 6, 2400, 1200, '①：只要这张卡在怪兽区域存在，自己场上的「星际仙踪」卡被战斗或者对方的效果破坏的场合，可以作为代替把自己场上1张「星际仙踪」卡破坏。 ②：这张卡被战斗·效果破坏送去墓地的场合，把墓地的这张卡除外才能发动。从卡组把1只5星以下的「星际仙踪」怪兽特殊召唤。'),
(82270047, 'Kozmo Lightsword', '星际仙踪-光线剑', 'Kozmo－レイブレード', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '念动力族「星际仙踪」怪兽才能装备。「星际仙踪-光线剑」的②的效果1回合只能使用1次。 ①：装备怪兽攻击力·守备力上升500，同1次的战斗阶段中最多2次可以向怪兽攻击，向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。 ②：这张卡从场上送去墓地的场合，支付800基本分才能发动。墓地的这张卡加入手卡。'),
(86013171, 'Kozmo Scaredy Lion', '星际仙踪-小胆', 'Kozmo－パーヴィッド', 'Effect Monster', 'Psychic', 'LIGHT', 2, 1200, 500, '「星际仙踪-小胆」的①的效果1回合只能使用1次。 ①：把场上的这张卡除外才能发动。从手卡把1只3星以上的「星际仙踪」怪兽特殊召唤。这个效果在对方回合也能发动。 ②：1回合1次，支付500基本分，以除外的3只自己的「星际仙踪」怪兽为对象才能发动。那些怪兽回到墓地，给与对方500伤害。'),
(94454495, 'Kozmo Sliprider', '星际仙踪-魔鞋骑手', 'Kozmo－スリップライダー', 'Effect Monster', 'Machine', 'LIGHT', 5, 2300, 800, '①：这张卡召唤·特殊召唤成功的场合，以场上1张魔法·陷阱卡为对象才能发动。那张卡破坏。 ②：这张卡被战斗·效果破坏送去墓地的场合，把墓地的这张卡除外才能发动。从卡组把1只4星以下的「星际仙踪」怪兽特殊召唤。'),
(1274455, 'Kozmo Soartroopers', '星际仙踪-飞猴队', 'Kozmo－シーミウズ', 'Effect Monster', 'Psychic', 'DARK', 3, 1000, 1000, '「星际仙踪-飞猴队」的①的效果1回合只能使用1次。 ①：把场上的这张卡除外才能发动。从手卡把1只4星以上的「星际仙踪」怪兽特殊召唤。这个效果在对方回合也能发动。 ②：1回合1次，支付1000基本分，以自己墓地1只念动力族「星际仙踪」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(56907986, 'Kozmo Strawman', '星际仙踪-稻草人', 'Kozmo－フォルミート', 'Effect Monster', 'Psychic', 'LIGHT', 2, 500, 1800, '「星际仙踪-稻草人」的①的效果1回合只能使用1次。 ①：把场上的这张卡除外才能发动。从手卡把1只3星以上的「星际仙踪」怪兽特殊召唤。这个效果在对方回合也能发动。 ②：1回合1次，支付500基本分，以除外的1只自己的「星际仙踪」怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化，结束阶段破坏。'),
(64280356, 'Kozmo Tincan', '星际仙踪-铁皮', 'Kozmo－フェルブラン', 'Effect Monster', 'Psychic', 'LIGHT', 1, NULL, NULL, '「星际仙踪-铁皮」的①的效果1回合只能使用1次。 ①：把场上的这张卡除外才能发动。从手卡把1只2星以上的「星际仙踪」怪兽特殊召唤。这个效果在对方回合也能发动。 ②：自己·对方的结束阶段支付500基本分才能发动。从卡组把「星际仙踪」卡3种类给对方观看，对方从那之中随机选1张。那1张卡加入自己手卡，剩余送去墓地。'),
(90452877, 'Kozmojo', '星际仙踪-能术', 'Kozmo－エナジーアーツ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '「星际仙踪-能术」在1回合只能发动1张。 ①：以自己场上1只「星际仙踪」怪兽为对象才能发动。那只怪兽破坏，选对方的场上·墓地1张卡除外。'),
(12408276, 'Kozmoll Dark Lady', '星际仙踪-达克·艾伐芭', 'Kozmo－ダーク・エルファイバー', 'Effect Monster', 'Psychic', 'DARK', 5, 2200, 1800, '「星际仙踪-达克·艾伐芭」的①的效果1回合只能使用1次。 ①：把场上的这张卡除外才能发动。从手卡把1只6星以上的「星际仙踪」怪兽特殊召唤。这个效果在对方回合也能发动。 ②：1回合1次，这张卡以外的怪兽的效果发动时，支付1000基本分才能发动。那个发动无效并破坏。'),
(93302695, 'Kozmoll Wickedwitch', '星际仙踪-达克·萝丝', 'Kozmo－ダーク・ローズ', 'Effect Monster', 'Psychic', 'DARK', 4, 1900, 300, '「星际仙踪-达克·萝丝」的①的效果1回合只能使用1次。 ①：把场上的这张卡除外才能发动。从手卡把1只5星以上的「星际仙踪」怪兽特殊召唤。这个效果在对方回合也能发动。 ②：1回合1次，支付1000基本分才能发动。这个回合，这张卡不会被战斗·效果破坏。这个效果在对方回合也能发动。'),
(67237709, 'Kozmotown', '星际仙踪-翠玉都', 'Kozmo－エメラルドポリス', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：1回合1次，以除外的1只自己的「星际仙踪」怪兽为对象才能发动。那只怪兽回到手卡，自己失去那只怪兽的原本等级×100基本分。 ②：1回合1次，自己主要阶段才能发动。手卡的「星际仙踪」怪兽任意数量给对方观看，回到卡组洗切。那之后，自己从卡组抽出回到卡组的数量。 ③：场地区域的这张卡被效果破坏的场合才能发动。从卡组把1张「星际仙踪」卡加入手卡。'),
(12385638, 'Kozmourning', '星际仙踪-尾声', 'Kozmo－エピローグ', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，自己的「星际仙踪」怪兽战斗破坏的怪兽不送去墓地回到持有者卡组。 ②：把墓地的这张卡除外才能发动。这个回合，自己的「星际仙踪」怪兽的战斗让自己受到战斗伤害的场合只有1次，作为代替让自己基本分回复那个数值。'),
(15710054, 'Krawler Axon', '机怪虫・轴突', 'クローラー・アクソン', 'Flip Effect Monster', 'Insect', 'EARTH', 2, 500, 1800, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡反转的场合，以场上1张魔法·陷阱卡为对象才能发动。那张卡破坏。 ②：表侧表示的这张卡因对方的效果从场上离开的场合才能发动。「机怪虫·轴突虫」以外的2只「机怪虫」怪兽从卡组里侧守备表示特殊召唤（同名卡最多1张）。'),
(46083111, 'Krawler Dendrite', '机怪虫・树突', 'クローラー・デンドライト', 'Flip Effect Monster', 'Insect', 'EARTH', 2, 1300, 600, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡反转的场合才能发动。从卡组把1只怪兽送去墓地。 ②：表侧表示的这张卡因对方的效果从场上离开的场合才能发动。「机怪虫·树突虫」以外的2只「机怪虫」怪兽从卡组里侧守备表示特殊召唤（同名卡最多1张）。'),
(51205763, 'Krawler Glial', '机怪虫・胶质细胞', 'クローラー・グリア', 'Flip Effect Monster', 'Insect', 'EARTH', 2, 700, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡反转的场合才能发动。从自己的手卡·墓地选「机怪虫·神经胶质虫」以外的1只「机怪虫」怪兽表侧攻击表示或者里侧守备表示特殊召唤。 ②：表侧表示的这张卡因对方的效果从场上离开的场合才能发动。「机怪虫·神经胶质虫」以外的2只「机怪虫」怪兽从卡组里侧守备表示特殊召唤（同名卡最多1张）。'),
(10698416, 'Krawler Ranvier', '机怪虫・兰氏结', 'クローラー・ランヴィエ', 'Flip Effect Monster', 'Insect', 'EARTH', 2, 1100, 900, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡反转的场合，以自己墓地最多2只「机怪虫」怪兽为对象才能发动。那些怪兽加入手卡。 ②：表侧表示的这张卡因对方的效果从场上离开的场合才能发动。「机怪虫·郎飞结虫」以外的2只「机怪虫」怪兽从卡组里侧守备表示特殊召唤（同名卡最多1张）。'),
(83293307, 'Krawler Receptor', '机怪虫・神经受体', 'クローラー・レセプター', 'Flip Effect Monster', 'Insect', 'EARTH', 2, 900, 1200, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡反转的场合才能发动。从卡组把1只「机怪虫」怪兽加入手卡。 ②：表侧表示的这张卡因对方的效果从场上离开的场合才能发动。「机怪虫·受体虫」以外的2只「机怪虫」怪兽从卡组里侧守备表示特殊召唤（同名卡最多1张）。'),
(63526052, 'Krawler Soma', '机怪虫・细胞体', 'クローラー・ソゥマ', 'Effect Monster', 'Insect', 'EARTH', 6, 2000, 2500, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1只表侧表示怪兽为对象才能发动。这张卡从手卡特殊召唤，作为对象的怪兽变成里侧守备表示。这个回合，作为对象的怪兽不能把表示形式变更。 ②：自己主要阶段才能发动。这张卡的等级下降2星或者4星，等级合计直到变成和下降数值相同为止，从自己的手卡·卡组·墓地选「机怪虫」怪兽表侧守备表示或里侧守备表示特殊召唤（同名卡最多1张）。'),
(88316955, 'Krawler Spine', '机怪虫・棘', 'クローラー・スパイン', 'Flip Effect Monster', 'Insect', 'EARTH', 2, 300, 2100, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡反转的场合，以场上1只怪兽为对象才能发动。那只怪兽破坏。 ②：表侧表示的这张卡因对方的效果从场上离开的场合才能发动。「机怪虫·树突棘虫」以外的2只「机怪虫」怪兽从卡组里侧守备表示特殊召唤（同名卡最多1张）。'),
(59575539, 'Krebons', '天眼通', 'クレボンス', 'Tuner Monster', 'Psychic', 'DARK', 2, 1200, 400, '这张卡被选择作为攻击对象时，支付800基本分才能发动。那次攻击无效。'),
(37006702, 'Krishnerd Witch', '克里希那德女巫', 'クリシュナード・ウィッチ', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 1800, 700, '这个卡名的①③的效果1回合各能使用1次。 ①：场地区域的卡因效果从场上离开的场合才能发动。这张卡从手卡特殊召唤。 ②：只要场上有「多元宇宙」存在，这张卡不会被对方的效果破坏。 ③：已是表侧表示存在的场地魔法卡的效果发动时才能发动。自己的墓地·除外状态的1只怪兽回到卡组。那只怪兽有那张发动的场地魔法卡的卡名记述的场合，可以不回到卡组特殊召唤。'),
(76512652, 'Krokodilus', '鳄鱼人', 'クロコダイラス', 'Normal Monster', 'Reptile', 'WATER', 4, 1100, 1200, '有智慧而且狂暴化的鳄鱼。以坚硬的鳞片反弹对方的攻击。'),
(20960340, 'Krystal Avatar', '水晶化身', 'クリスタル・アバター', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：对方怪兽的直接攻击宣言时，那只怪兽的攻击力是自己基本分以上的场合才能发动。这张卡发动后变成和自己基本分数值相同攻击力的效果怪兽（战士族·光·4星·攻?/守0）在怪兽区域攻击表示特殊召唤。那之后，攻击对象转移为这张卡。这张卡也当作陷阱卡使用。 ②：这张卡的效果特殊召唤的这张卡被战斗破坏的伤害计算后发动。给与对方这张卡的攻击力数值的伤害。'),
(77363314, 'Krystal Dragon', '水晶龙', 'クリスタル・ドラゴン', 'Effect Monster', 'Dragon', 'LIGHT', 6, 2500, 1000, '①：1回合1次，这张卡进行过战斗的自己回合的战斗步骤才能发动。从卡组把1只龙族·8星怪兽加入手卡。'),
(82642348, 'Kryuel', '残酷', 'クルーエル', 'Effect Monster', 'Fiend', 'DARK', 4, 1000, 1700, '这张卡被战斗破坏送去墓地时，投掷1个硬币猜正反。猜中的场合破坏对方1只怪兽。'),
(20087414, 'Kuebiko', '久延毘古', '久延毘古', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：这张卡发动后变成持有以下效果的效果怪兽（天使族·地·2星·攻/守0）在怪兽区域特殊召唤（也当作陷阱卡使用）。 ●自己场上的卡为对象的场上的怪兽的效果由对方发动时才能发动（同一连锁上最多1次）。这张卡在自己的魔法与陷阱区域盖放，那个对方的效果无效。那只怪兽的攻击力是对方场上最高的场合，再让那只怪兽回到手卡。'),
(87837090, 'Kuibelt the Blade Dragon', '带刃龙 柯伊铠带龙', '帯刃龍 カイベルト', 'Synchro Monster', 'Dragon', 'DARK', 7, 2500, 1900, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡同调召唤的场合，以场上1张卡为对象才能发动。那张卡破坏。 ②：场上的这张卡被破坏的场合，以场上1只表侧表示怪兽为对象才能发动。那只怪兽直到对方回合结束时不能攻击。'),
(24384095, 'Kujakujaku', '九蛇孔雀', '九蛇孔雀', 'Effect Monster', 'Winged Beast', 'WIND', 3, 1200, 900, '场上的这张卡被解放送去墓地的场合，可以从自己的卡组·墓地选「九蛇孔雀」以外的1只4星以下的风属性怪兽加入手卡。「九蛇孔雀」的效果1回合只能使用1次。'),
(78543464, 'Kuji-Kiri Curse', '切纸九字的咒符', '九字切りの呪符', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从手卡以及自己场上的表侧表示怪兽之中把1只9星怪兽送去墓地才能发动。自己从卡组抽2张。'),
(29726552, 'Kumongous, the Sticky String Kaiju', '粘丝坏兽 蛛默鼓丝', '粘糸壊獣クモグス', 'Effect Monster', 'Insect', 'EARTH', 7, 2400, 2500, '①：这张卡可以把对方场上1只怪兽解放，从手卡往对方场上攻击表示特殊召唤。 ②：对方场上有「坏兽」怪兽存在的场合，这张卡可以从手卡攻击表示特殊召唤。 ③：「坏兽」怪兽在自己场上只能有1只表侧表示存在。 ④：对方对怪兽的召唤·特殊召唤成功时，把自己·对方场上2个坏兽指示物取除才能发动。直到下个回合的结束时，那些怪兽不能攻击，效果无效化。'),
(56283725, 'Kumootoko', '蜘蛛男', '蜘蛛男', 'Normal Monster', 'Insect', 'EARTH', 3, 700, 1400, '巨大的蜘蛛被赋予智慧的形态，通过吐丝将敌人的行动封锁。'),
(37390589, 'Kunai with Chain', '锁链飞镖', '鎖付きブーメラン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：从以下效果选择1个或者两方才能把这张卡发动。 ●对方怪兽的攻击宣言时，以那1只攻击怪兽为对象才能发动。那只攻击怪兽变成守备表示。 ●以自己场上1只表侧表示怪兽为对象才能发动。这张卡当作攻击力上升500的装备卡使用给那只自己怪兽装备。'),
(56514812, 'Kunoichi', '女忍战士', 'くノ一ウォリアー', 'Effect Monster', 'Warrior', 'WIND', 4, 1800, 1000, '场上表侧表示存在的这张卡的控制权转移时，控制者把手卡随机丢弃1张。'),
(85705804, 'Kurama', '鸭人', 'ドレイク', 'Normal Monster', 'Winged Beast', 'WIND', 3, 800, 800, '尾巴很长的鸟，从空中发起攻击。'),
(57666212, 'Kuraz the Light Monarch', '光帝克莱斯', '光帝クライス', 'Effect Monster', 'Warrior', 'LIGHT', 6, 2400, 1000, '①：这张卡召唤·特殊召唤成功时，以场上最多2张卡为对象才能发动。那些卡破坏，破坏的卡的控制者可以从卡组抽出破坏的数量。 ②：这张卡在召唤·特殊召唤的回合不能攻击。'),
(70914287, 'Kuribabylon', '巴比伦栗子', 'クリバビロン', 'Effect Monster', 'Fiend', 'DARK', 5, 1500, 1000, '这个卡名的①③的效果1回合只能有1次使用其中任意1个。 ①：自己墓地的怪兽数量比对方墓地的怪兽多的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡的攻击力·守备力上升自己的场上·墓地的「栗子球」怪兽数量×300。 ③：自己的主要阶段以及战斗阶段才能发动。这张卡回到持有者手卡，从自己的手卡·墓地选「栗子丸」「栗子团」「栗子圆」「栗子珠」「栗子球」各1只攻击表示特殊召唤。');